"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["89648"],{65648(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.endereco_referencia.cidade_obrigatoria_com_endereco","status":422,"titulo":"Endere\xe7o informado exige a refer\xeancia de cidade da entidade"},"descricao":{"codigo":"uniplus.endereco_referencia.cidade_obrigatoria_com_endereco","requisitos":[],"oQueAconteceu":["O cadastro da institui\xe7\xe3o trouxe o endere\xe7o estruturado da sede, mas nenhum dos tr\xeas campos da cidade da sede: `cidadeCodigoIbge`, `cidadeNome` e `cidadeUf` est\xe3o ausentes, vazios ou s\xf3 com espa\xe7os. A mensagem \xe9 `A cidade da sede \xe9 obrigat\xf3ria quando h\xe1 endere\xe7o estruturado.` A cidade da institui\xe7\xe3o \xe9 opcional quando n\xe3o h\xe1 endere\xe7o, e \xe9 s\xf3 o endere\xe7o que a torna obrigat\xf3ria.","A confer\xeancia ocorre depois da recusa dos pr\xf3prios campos da cidade: com a cidade preenchida s\xf3 em parte, a resposta traz as recusas de [refer\xeancia de cidade](/erros/uniplus.cidade_referencia.codigo_ibge_obrigatorio) para o que falta, e n\xe3o esta. Quando a cidade est\xe1 completa, a confer\xeancia seguinte \xe9 a de [cidade do endere\xe7o diferente da do cadastro](/erros/uniplus.endereco_referencia.cidade_incoerente). A recusa vale para o endere\xe7o enviado, e n\xe3o depende de a institui\xe7\xe3o j\xe1 ter ou n\xe3o ter cidade gravada.","O endere\xe7o estruturado \xe9 opcional no cadastro do campus, do local de oferta e da institui\xe7\xe3o (a sede): sem o objeto `endereco` no corpo da requisi\xe7\xe3o, nenhuma confer\xeancia dele ocorre. Com o objeto, a API confere os campos um de cada vez e para na primeira recusa, nesta ordem: CEP informado, CEP com 8 d\xedgitos, cidade do endere\xe7o (as recusas da fam\xedlia [refer\xeancia de cidade](/erros/uniplus.cidade_referencia.codigo_ibge_obrigatorio)), tamanho dos textos (logradouro, n\xfamero, complemento, bairro e distrito), latitude, longitude, n\xedvel de resolu\xe7\xe3o informado, n\xedvel de resolu\xe7\xe3o dentro do vocabul\xe1rio, origem informada e tamanho da origem.","A recusa vem na lista `errors` da resposta, com `field` igual a `endereco`, ao lado das recusas dos outros campos do mesmo cadastro, que s\xe3o conferidos no mesmo pedido. O `code` da resposta \xe9 o da primeira recusa da lista, e as recusas dos campos do pr\xf3prio cadastro (como `sigla`, `nome` e a cidade) v\xeam antes da do endere\xe7o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, estas confer\xeancias v\xeam antes da busca do registro: um `{id}` que n\xe3o existe, enviado com endere\xe7o recusado, recebe esta recusa, e s\xf3 o corpo aceito chega \xe0 resposta de [campus n\xe3o encontrado](/erros/uniplus.configuracao.campus.nao_encontrado), de [local de oferta n\xe3o encontrado](/erros/uniplus.configuracao.local_oferta.nao_encontrado) ou de [institui\xe7\xe3o n\xe3o encontrada](/erros/uniplus.organizacao.instituicao.nao_encontrada)."],"comoResolver":["Informe a cidade da sede (`cidadeCodigoIbge`, `cidadeNome` e `cidadeUf`), coerente com a cidade do endere\xe7o, ou retire o objeto `endereco` do corpo."],"ondeAparece":["Cria\xe7\xe3o da institui\xe7\xe3o","Atualiza\xe7\xe3o da institui\xe7\xe3o"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Endereco referencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);